import type { LanguageLesson } from "./types";

type Guide = {
  focusVi: string;
  focusEn: string;
  recogniseVi: string[];
  recogniseEn: string[];
  stepsVi: string[];
  stepsEn: string[];
  evidenceVi: string;
  evidenceEn: string;
  trapsVi: string[];
  trapsEn: string[];
  exampleVi: string;
  exampleEn: string;
  checkVi: string[];
  checkEn: string[];
  tipsVi?: string[];
  tipsEn?: string[];
};

const section = (title: string, body: string) => `### ${title}\n${body}`;
const bullets = (items: string[]) => items.map((item) => `- ${item}`).join("\n");
const steps = (items: string[]) => items.map((item, index) => `${index + 1}. ${item}`).join("\n");

const render = (guide: Guide, language: "vi" | "en") => {
  const vi = language === "vi";
  return [
    section(vi ? "Mục tiêu" : "What this skill tests", vi ? guide.focusVi : guide.focusEn),
    section(vi ? "Nhận diện yêu cầu" : "Recognise the task", bullets(vi ? guide.recogniseVi : guide.recogniseEn)),
    section(vi ? "Quy trình làm bài" : "Step-by-step method", steps(vi ? guide.stepsVi : guide.stepsEn)),
    section(vi ? "Cách xác nhận bằng chứng" : "Confirming the evidence", vi ? guide.evidenceVi : guide.evidenceEn),
    section(vi ? "Bẫy thường gặp" : "Common traps", bullets(vi ? guide.trapsVi : guide.trapsEn)),
    section(vi ? "Ví dụ có giải thích" : "Worked example", vi ? guide.exampleVi : guide.exampleEn),
    section(vi ? "Checklist trước khi chốt" : "Final checklist", bullets(vi ? guide.checkVi : guide.checkEn)),
  ].join("\n\n");
};

