export const applyIeltsReadingTheoryGuides = (lessons: LanguageLesson[]): LanguageLesson[] =>
  lessons.map((lesson) => {
    const guide = guides[lesson.id];
    if (!guide) return lesson;
    return {
      ...lesson,
      theory: render(guide, "vi"),
      theoryEn: render(guide, "en"),
      ...(guide.tipsVi ? { proTips: guide.tipsVi } : {}),
      ...(guide.tipsEn ? { proTipsEn: guide.tipsEn } : {}),
    };
  });

export const IELTS_READING_THEORY_GUIDE_IDS = Object.freeze(Object.keys(guides));
